import json, os, re, shutil, zipfile
from lxml import etree

# Load JSON
with open('/root/project_proposal.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# Normalize budget: remove commas, keep currency symbol
# (In this dataset it's the "예산" field, formatted like "₩450,000,000")
CURRENCY_MARKERS = ['₩', '$', '€', '¥', '원']

def normalize_currency(s: str) -> str:
    if any(c in s for c in CURRENCY_MARKERS):
        return s.replace(',', '')
    return s

if isinstance(data, dict):
    for k, v in list(data.items()):
        if isinstance(v, str):
            data[k] = normalize_currency(v)

# If data has nested structure, flatten it for placeholder matching
# (This JSON is flat, but we keep flattening for robustness.)
def flatten_json(obj, prefix=''):
    items = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_key = f"{prefix}.{k}" if prefix else k
            if isinstance(v, (dict, list)):
                items.update(flatten_json(v, new_key))
            else:
                items[new_key] = str(v)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            new_key = f"{prefix}[{i}]" if prefix else f"[{i}]"
            items.update(flatten_json(v, new_key))
    return items

flat_data = flatten_json(data)

template_dir = '/tmp/hwpx_work/template_contents'
output_dir = '/tmp/hwpx_work/output_contents'

# Copy template to output
if os.path.exists(output_dir):
    shutil.rmtree(output_dir)
shutil.copytree(template_dir, output_dir)

# Find all XML files with placeholders
xml_files = []
for root, dirs, files in os.walk(output_dir):
    for fname in files:
        if not fname.endswith('.xml'):
            continue
        fpath = os.path.join(root, fname)
        with open(fpath, 'r', encoding='utf-8') as fh:
            content = fh.read()
        if '{{' in content:
            xml_files.append(fpath)

print(f"Files with placeholders: {xml_files}")
print(f"Flat replacement map keys: {list(flat_data.keys())}")

# Month span logic
# - Range: 2026-08 ~ 2026-10 (inclusive) => 3 months
# - Single: 2027-01 => 1 month
RANGE_RE = re.compile(r'(\d{4})[.\-/](\d{1,2})\s*[~\-–—]\s*(\d{4})[.\-/](\d{1,2})')
SINGLE_RE = re.compile(r'(\d{4})[.\-/](\d{1,2})')

def compute_months_from_text(text: str):
    m = RANGE_RE.search(text)
    if m:
        y1, mo1, y2, mo2 = int(m.group(1)), int(m.group(2)), int(m.group(3)), int(m.group(4))
        return (y2 - y1) * 12 + (mo2 - mo1 + 1)

    # If there's no range, but there is a single YYYY-MM somewhere (e.g. "(2027-01)") treat as 1 month.
    m2 = SINGLE_RE.search(text)
    if m2:
        return 1

    return None

# Placeholder replacement at the XML text node level
PH_RE = re.compile(r'\{\{([^}]+)\}\}')

def localname(tag: str) -> str:
    return tag.split('}', 1)[-1] if '}' in tag else tag

for fpath in xml_files:
    print(f"\nProcessing: {fpath}")

    with open(fpath, 'rb') as fh:
        raw = fh.read()

    try:
        tree = etree.fromstring(raw)
    except Exception as e:
        raise SystemExit(f"Failed to parse XML {fpath}: {e}")

    # Replace placeholders in all <...:t> text nodes
    found_placeholders = []
    replaced = 0

    for t in tree.iter():
        if localname(t.tag) != 't':
            continue
        if not isinstance(t.text, str) or '{{' not in t.text:
            continue

        def repl(m):
            nonlocal replaced
            ph = m.group(1).strip()
            found_placeholders.append(ph)

            # Exact match first
            if ph in flat_data:
                val = flat_data[ph]
            else:
                # Case-insensitive fallback
                val = None
                for k, v in flat_data.items():
                    if k.lower() == ph.lower():
                        val = v
                        break
                if val is None:
                    print(f"  WARNING: No match for placeholder '{ph}'")
                    return m.group(0)  # keep as-is for later reporting

            # Currency normalization (defensive)
            val = normalize_currency(val)

            replaced += 1
            return val

        t.text = PH_RE.sub(repl, t.text)

    print(f"  Placeholders found: {found_placeholders}")
    print(f"  Replacements made: {replaced}")

    # Append month spans for phase lines: 1단계/2단계/3단계
    # The phase content lives in <hp:t> strings like "1단계: ... (2026-08 ~ 2026-10)"
    phase_appended = 0
    for t in tree.iter():
        if localname(t.tag) != 't':
            continue
        if not isinstance(t.text, str):
            continue
        if '단계' not in t.text:
            continue
        if re.search(r'\(\d+개월\)', t.text):
            continue

        months = compute_months_from_text(t.text)
        if months:
            t.text = f"{t.text} ({months}개월)"
            phase_appended += 1

    if phase_appended:
        print(f"  Appended month spans to {phase_appended} phase line(s)")

    # Remove layout cache elements (linesegarray, lineSeg)
    removed = 0
    for elem in list(tree.iter()):
        ln = localname(elem.tag).lower()
        if ln in ('linesegarray', 'lineseg'):
            parent = elem.getparent()
            if parent is not None:
                parent.remove(elem)
                removed += 1
    print(f"  Removed {removed} layout cache elements")

    # Write back
    out = etree.tostring(tree, xml_declaration=True, encoding='UTF-8', pretty_print=False)
    with open(fpath, 'wb') as fh:
        fh.write(out)

# Verify no placeholders remain
for fpath in xml_files:
    with open(fpath, 'r', encoding='utf-8') as fh:
        content = fh.read()
    remaining = re.findall(r'\{\{[^}]+\}\}', content)
    if remaining:
        print(f"WARNING: Remaining placeholders in {fpath}: {remaining}")
    else:
        print(f"OK: No placeholders remain in {fpath}")

# Repackage as HWPX (ZIP)
output_hwpx = '/root/project_proposal_ready.hwpx'
if os.path.exists(output_hwpx):
    os.remove(output_hwpx)

with zipfile.ZipFile(output_hwpx, 'w', zipfile.ZIP_DEFLATED) as zout:
    for root, dirs, files in os.walk(output_dir):
        for fname in files:
            fpath = os.path.join(root, fname)
            arcname = os.path.relpath(fpath, output_dir)
            zout.write(fpath, arcname)

print(f"\nOutput written to {output_hwpx}")

# Final verification inside the produced ZIP
with zipfile.ZipFile(output_hwpx, 'r') as zf:
    print(f"ZIP entries: {zf.namelist()}")
    for name in zf.namelist():
        if not name.endswith('.xml'):
            continue
        text = zf.read(name).decode('utf-8')
        remaining = re.findall(r'\{\{[^}]+\}\}', text)
        if remaining:
            print(f"  FAIL: {name} still has: {remaining}")
        else:
            print(f"  OK: {name}")

