        if '단계' not in t.text:
            continue
        if re.search(r'\(\d+개월\)', t.text):
            continue

        months = compute_months_from_text(t.text)
        if months:
            t.text = f"{t.text} ({months}개월)"
            phase_appended += 1

    if phase_appended:
        print(f"  Appended month spans to {phase_appended} phase line(s)")

    # Remove layout cache elements (linesegarray, lineSeg)
    removed = 0

    def remove_children_by_localname(parent, names):
        nonlocal removed
        # iterate over a snapshot because we'll mutate
        for child in list(parent):
            if localname(child.tag).lower() in names:
                parent.remove(child)
                removed += 1
            else:
                remove_children_by_localname(child, names)

    remove_children_by_localname(root, {'linesegarray', 'lineseg'})
    print(f"  Removed {removed} layout cache elements")

    # Write back
    tree.write(fpath, encoding='UTF-8', xml_declaration=True)

# Verify no placeholders remain
for fpath in xml_files:
